package jp.yaegaki.equipment;
import android.app.*;import android.content.DialogInterface;import android.graphics.*;import android.text.InputType;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
final class GeminiUi {
 final MainActivity a;Gemini active;final ExecutorService worker=Executors.newSingleThreadExecutor();boolean busy;
 GeminiUi(MainActivity activity){a=activity;}
 void close(){cancel();worker.shutdownNow();}
 void cancel(){if(active!=null)active.cancel();}
 void settings(){try{JSONObject saved=a.store.aiSettings();LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(a.dp(20),a.dp(10),a.dp(20),a.dp(10));a.text(box,"APIキーはこの端末内に暗号化して保存します。APK・バックアップには含めません。",14,MainActivity.MUTED,false);EditText key=a.field(box,saved.optString("key").isEmpty()?"Gemini APIキー":"APIキー（設定済み・変更する場合のみ入力）","",false);key.setInputType(129);key.setHint(saved.optString("key").isEmpty()?"APIキーを貼り付け":"変更しない場合は空欄");EditText model=a.field(box,"モデル名",saved.optString("model","gemini-2.5-flash"),false);a.text(box,"写真を選んでAI解析するとGoogle Geminiへ送信され、API利用料が発生する場合があります。通常のOCRは端末内処理です。",13,MainActivity.MUTED,false);AlertDialog d=a.new SafeBuilder(a).setTitle("Gemini AI設定").setView(box).setPositiveButton("保存",null).setNeutralButton("キーを削除",(v,w)->{try{a.store.aiSettings(new JSONObject());a.message("削除しました","この端末に保存したAPIキーを削除しました。");}catch(Exception e){a.error(e);}}).setNegativeButton("戻る",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String k=key.getText().toString().trim();if(k.isEmpty())k=saved.optString("key");String m=model.getText().toString().trim();if(k.isEmpty()){key.setError("APIキーを入力してください");return;}if(!m.matches("[A-Za-z0-9._-]+")){model.setError("モデル名を確認してください");return;}try{a.store.aiSettings(new JSONObject().put("key",k).put("model",m));key.setText("");d.dismiss();a.message("設定を保存しました","機器の編集画面から「Geminiでメーカー・型番を識別」を使えます。");}catch(Exception e){a.error(e);}}));d.show();}catch(Exception e){a.error(e);}}
 void choose(){if(!a.edit||!a.unlocked||busy)return;if(a.photoBusy){a.message("写真処理中","写真の保存後にお試しください。");return;}try{if(a.store.aiSettings().optString("key").isEmpty()){settings();return;}JSONArray photos=a.current.optJSONArray("photos");if(photos==null||photos.length()==0){a.message("写真を追加してください","本体と銘板の写真を登録してからAI解析してください。");return;}a.persistDraft();ScrollView scroll=new ScrollView(a);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(8));scroll.addView(box);a.text(box,"送信する写真を1〜4枚選んでください。選んだ写真だけをGoogle Geminiへ送ります。台帳の入力内容は送りません。写真に写っている情報は送信されます。",14,MainActivity.MUTED,false);ArrayList<CheckBox> checks=new ArrayList<>();for(int i=0;i<photos.length();i++){JSONObject ph=photos.getJSONObject(i);CheckBox cb=new CheckBox(a);cb.setText((i+1)+". "+ph.optString("kind"));box.addView(cb);checks.add(cb);ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);box.addView(image,new LinearLayout.LayoutParams(-1,a.dp(110)));a.worker.execute(()->{try{byte[] bytes=a.store.photo(ph.getString("file"));BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=4;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);a.runOnUiThread(()->image.setImageBitmap(b));}catch(Exception ignored){}});}AlertDialog d=a.new SafeBuilder(a).setTitle("Geminiで写真を解析").setView(scroll).setPositiveButton("選択した写真を送信",null).setNegativeButton("戻る",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{ArrayList<String> ids=new ArrayList<>();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked())ids.add(photos.optJSONObject(i).optString("file"));if(ids.isEmpty()||ids.size()>4){a.message("写真を選択","1〜4枚を選んでください。");return;}d.dismiss();analyze(ids);}));d.show();}catch(Exception e){a.error(e);}}
 void analyze(List<String> ids){if(busy)return;try{JSONObject settings=a.store.aiSettings();String key=settings.optString("key"),model=settings.optString("model","gemini-2.5-flash");JSONObject target=a.current;Gemini client=new Gemini();active=client;busy=true;ProgressDialog progress=new ProgressDialog(a);progress.setTitle("Geminiで解析中");progress.setMessage("メーカー・型番の候補を確認しています…");progress.setIndeterminate(true);progress.setCancelable(true);progress.setOnCancelListener(d->client.cancel());progress.setButton(DialogInterface.BUTTON_NEGATIVE,"中止",(d,w)->client.cancel());a.dialogs.add(progress);progress.show();worker.execute(()->{try{ArrayList<byte[]> images=new ArrayList<>();for(String id:ids){if(client.cancelled)return;images.add(a.store.photo(id));}JSONObject result=client.identify(key,model,images);a.runOnUiThread(()->{if(!client.cancelled&&!a.isDestroyed()&&a.unlocked&&a.edit&&a.current==target)review(result);});}catch(Exception e){a.runOnUiThread(()->{if(!client.cancelled&&!a.isDestroyed()&&a.unlocked)a.message("AI解析を完了できませんでした",e.getMessage());});}finally{a.runOnUiThread(()->{busy=false;if(active==client)active=null;progress.dismiss();});}});}catch(Exception e){busy=false;a.error(e);}}
 void review(JSONObject result){JSONArray rows=result.optJSONArray("fields");ScrollView scroll=new ScrollView(a);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(8));scroll.addView(box);a.text(box,"反映する項目にチェックしてください。AIの候補は誤る場合があります。既存の入力は選んだ項目だけを置き換えます。",14,MainActivity.MUTED,false);if(!result.optString("summary").isEmpty())a.text(box,result.optString("summary"),14,MainActivity.INK,false);LinkedHashMap<String,EditText> values=new LinkedHashMap<>();LinkedHashMap<String,CheckBox> checks=new LinkedHashMap<>();for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.optJSONObject(i);String key=row.optString("key");if(!a.inputs.containsKey(key))continue;String label=key;for(String[] f:MainActivity.F)if(f[0].equals(key))label=f[1];LinearLayout c=a.card(box);CheckBox cb=new CheckBox(a);cb.setText(label);cb.setChecked(false);c.addView(cb);checks.put(key,cb);String confidence=row.optString("confidence");a.text(c,"確度："+(confidence.equals("high")?"高（要確認）":confidence.equals("medium")?"中":"低・推測"),13,MainActivity.TEAL,true);values.put(key,a.field(c,"候補",row.optString("value"),key.equals("mac")||key.equals("ip")));a.text(c,"根拠："+row.optString("evidence"),13,MainActivity.MUTED,false);String old=a.inputs.get(key).getText().toString();if(!old.isEmpty())a.text(c,"現在："+old,13,MainActivity.MUTED,false);}if(checks.isEmpty())a.text(box,"候補が得られませんでした。銘板やロゴを明るく大きく撮り直してください。",15,MainActivity.INK,false);a.new SafeBuilder(a).setTitle("AIの候補を確認").setView(scroll).setPositiveButton("選択した項目を反映",(d,w)->{if(!a.edit||!a.unlocked)return;for(String key:checks.keySet())if(checks.get(key).isChecked())a.inputs.get(key).setText(values.get(key).getText());a.persistDraft();}).setNegativeButton("反映しない",null).show();}
}
